import { Component, OnInit } from '@angular/core';
import { jobSeeker } from 'src/app/auth/Models/jobSeeker';
import { ApplicationService } from 'src/app/service/application/application.service';
import { SeekerService } from 'src/app/service/seeker/seeker.service';
import { AuthStateService } from 'src/app/shared/services/auth-state.service';

@Component({
  selector: 'app-dashboard',
  templateUrl: './dashboard.component.html',
  styleUrls: ['./dashboard.component.css']
})
export class DashboardComponent implements OnInit {
  seeker!: jobSeeker;
  totalApplications = 0;

  constructor(
    private readonly seekerService: SeekerService,
    private readonly applicationService: ApplicationService,
    private readonly authState: AuthStateService
  ) {}

  get avatar(): string {
    return this.authState.initialsFromSeeker(this.seeker);
  }

  ngOnInit(): void {
    const id = this.authState.id;
    if (id === null) {
      return;
    }
    this.seekerService.getSeekerById(id).subscribe((res: jobSeeker) => {
      this.seeker = res;
    });
    this.applicationService.getApplicationByjobSeekerId(id).subscribe((result) => {
      this.totalApplications = Array.isArray(result) ? result.length : 0;
    });
  }

  logout(): void {
    this.authState.logout();
  }
}
